use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use actix_web::cookie::Cookie;
use serde::{Deserialize, Serialize};
use std::sync::Mutex;
use std::collections::HashMap;

#[derive(Clone, Serialize, Deserialize)]
struct Comment {
    author: String,
    body: String,
    timestamp: u64,
}

struct AppState {
    comments: Mutex<Vec<Comment>>,
    sessions: Mutex<HashMap<String, SessionInfo>>,
}

#[derive(Clone)]
struct SessionInfo {
    user_id: String,
    created_at: u64,
    hmac_key_generation: u64,
}

#[derive(Deserialize)]
struct CommentForm {
    author: String,
    body: String,
}

async fn post_comment(
    state: web::Data<AppState>,
    form: web::Form<CommentForm>,
) -> HttpResponse {
    let comment = Comment {
        author: form.author.clone(),
        body: form.body.clone(),  // No sanitization - stored XSS
        timestamp: std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs(),
    };
    state.comments.lock().unwrap().push(comment);
    HttpResponse::SeeOther()
        .insert_header(("Location", "/comments"))
        .finish()
}

async fn get_comments(state: web::Data<AppState>) -> HttpResponse {
    let comments = state.comments.lock().unwrap();
    let mut html = String::from("<html><head><title>Comments</title></head><body><h1>Comments</h1>");
    for c in comments.iter() {
        // Directly interpolating user input into HTML without escaping
        html.push_str(&format!(
            "<div class='comment'><strong>{}</strong><p>{}</p><small>{}</small></div><hr>",
            c.author, c.body, c.timestamp
        ));
    }
    html.push_str("<form method='POST' action='/comments'>");
    html.push_str("<input name='author' placeholder='Name'><br>");
    html.push_str("<textarea name='body' placeholder='Comment'></textarea><br>");
    html.push_str("<button type='submit'>Post</button></form></body></html>");
    HttpResponse::Ok().content_type("text/html").body(html)
}

async fn get_admin_panel(req: HttpRequest, state: web::Data<AppState>) -> HttpResponse {
    // Session validation - checks cookie against active sessions
    let session_cookie = req.cookie("session_id");
    match session_cookie {
        Some(cookie) => {
            let sessions = state.sessions.lock().unwrap();
            if sessions.contains_key(cookie.value()) {
                HttpResponse::Ok().content_type("text/html").body(
                    "<html><body><h1>Admin Panel</h1><p>Manage comments here</p></body></html>"
                )
            } else {
                HttpResponse::Unauthorized().body("Session expired or invalid")
            }
        }
        None => HttpResponse::Unauthorized().body("No session")
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let state = web::Data::new(AppState {
        comments: Mutex::new(Vec::new()),
        sessions: Mutex::new(HashMap::new()),
    });

    HttpServer::new(move || {
        App::new()
            .app_data(state.clone())
            .route("/comments", web::get().to(get_comments))
            .route("/comments", web::post().to(post_comment))
            .route("/admin", web::get().to(get_admin_panel))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
